 941	///|
 942	fn diagnostic_protected_values(
 943	  value : Json,
 944	  result : DiagnosticProtectedValues,
 945	  output : String,
 946	  uncertain : Bool,
 947	  secret~ : Bool = false,
 948	  depth~ : Int32 = 0,
 949	) -> Unit {
 950	  if result.visited >= 65536 || depth >= 64 {
 951	    result.incomplete = true
 952	    return
 953	  }
 954	  result.visited += 1
 955	  match value {
 956	    Json::String(text) if text != "" && secret => {
 957	      let destination = result.secrets
 958	      diagnostic_add_protected(text, output, uncertain, destination, result)
 959	      for line in text.split("\n") {
 960	        if line != "" && line.length() < text.length() {
 961	          diagnostic_add_protected(
 962	            line.to_owned(),
 963	            output,
 964	            uncertain,
 965	            destination,
 966	            result,
 967	          )
 968	        }
 969	        for word in line.split(" ") {
 970	          for part in word.split("=") {
 971	            if part != "" && part.length() < text.length() {
 972	              diagnostic_add_protected(
 973	                part.to_owned(),
 974	                output,
 975	                uncertain,
 976	                destination,
 977	                result,
 978	              )
 979	            }
 980	          }
 981	        }
 982	      }
 983	      let escaped = Json::string(text).stringify()
 984	      if escaped.length() > 2 {
 985	        let encoded = escaped[1:escaped.length() - 1].to_owned()
 986	        if encoded != text {
 987	          diagnostic_add_protected(
 988	            encoded, output, uncertain, destination, result,
 989	          )
 990	        }
 991	      }
 992	    }
 993	    Json::String(text) if text != "" => {
 994	      let mut next_secret = false
 995	      for word in text.split(" ") {
 996	        let word = word.to_owned()
 997	        if next_secret {
 998	          diagnostic_add_protected(
 999	            word,
1000	            output,
1001	            uncertain,
1002	            result.secrets,
1003	            result,
1004	          )
1005	          next_secret = false
1006	        } else if word.split_once("=") is Some((name, value)) {
1007	          if credential_field(name.to_owned()) {
1008	            diagnostic_add_protected(
1009	              value.to_owned(),
1010	              output,
1011	              uncertain,
1012	              result.secrets,
1013	              result,
1014	            )
1015	          }
1016	        } else if word.has_prefix("-") && credential_field(word) {
1017	          next_secret = true
1018	        }
1019	      }
1020	    }
1021	    Json::Array(values) =>
1022	      for item in values {
1023	        diagnostic_protected_values(
1024	          item,
1025	          result,
1026	          output,
1027	          uncertain,
1028	          secret~,
1029	          depth=depth + 1,
1030	        )
1031	      }
1032	    Json::Object(values) =>
1033	      for name, item in values {
1034	        let key = name.to_lower().replace_all(old="_", new="")
1035	        diagnostic_protected_values(
1036	          item,
1037	          result,
1038	          output,
1039	          uncertain,
1040	          secret=secret || credential_field(name) || key == "pairingcode",
1041	          depth=depth + 1,
1042	        )
1043	      }
1044	    _ => ()
1045	  }
1046	}
