1048	///|
1049	fn diagnostic_output(
1050	  output : Bytes,
1051	  environment : Map[String, String],
1052	  protected_input? : String,
1053	  protected_secrets? : Array[String],
1054	  omitted~ : Bool = false,
1055	) -> String? {
1056	  if output.length() == 0 {
1057	    return if omitted {
1058	      Some("[error details incomplete or truncated]")
1059	    } else {
1060	      None
1061	    }
1062	  }
1063	  let limit = if output.length() > 8192 { 8192 } else { output.length() }
1064	  let incomplete = omitted || limit < output.length()
1065	  let text = @utf8.decode_lossy(output[:limit])
1066	  let safeguards : DiagnosticProtectedValues = {
1067	    secrets: [],
1068	    visited: 0,
1069	    incomplete: false,
1070	  }
1071	  if protected_input is Some(input) {
1072	    diagnostic_protected_values(
1073	      @json.parse(input),
1074	      safeguards,
1075	      text,
1076	      incomplete,
1077	    ) catch {
1078	      _ => safeguards.incomplete = true
1079	    }
1080	  }
1081	  if safeguards.incomplete {
1082	    return Some(
1083	      "Error output omitted because protected input could not be fully matched\n[error details incomplete or truncated]",
1084	    )
1085	  }
1086	  Some(
1087	    diagnostic_text(
1088	      text,
1089	      environment~,
1090	      omitted=incomplete,
1091	      protected_secrets=safeguards.secrets + protected_secrets.unwrap_or([]),
1092	      incomplete_final_line=incomplete && output[limit - 1] != b'\n',
1093	    ),
1094	  )
1095	}
