1105	///|
1106	fn DiagnosticCapture::new(limit : Int32) -> DiagnosticCapture {
1107	  {
1108	    output: @buffer.Buffer(size_hint=if limit < 4096 { limit } else { 4096 }),
1109	    limit,
1110	    truncated: false,
1111	    finished: false,
1112	  }
1113	}
