1157	///|
1158	async fn diagnostic_process_output(
1159	  program : String,
1160	  args : Array[String],
1161	  environment~ : Map[String, String],
1162	  cwd? : StringView,
1163	  stdin? : &@process.ProcessInput,
1164	  stdout_limit~ : Int32,
1165	  stderr_limit~ : Int32,
1166	) -> (Int32, Bytes, Bool, Bytes, Bool) {
1167	  let (out, stdout) = @process.read_from_process()
1168	  defer out.close()
1169	  let (err, stderr) = @process.read_from_process()
1170	  defer err.close()
1171	  @async.with_task_group(async fn(group) {
1172	    let child = @process.spawn(
1173	      group,
1174	      program,
1175	      args,
1176	      extra_env=environment,
1177	      inherit_env=false,
1178	      cwd?,
1179	      stdin?,
1180	      stdout~,
1181	      stderr~,
1182	    )
1183	    let output = DiagnosticCapture::new(stdout_limit)
1184	    let errors = DiagnosticCapture::new(stderr_limit)
1185	    group.spawn_bg(no_wait=true, async fn() { output.read(out) })
1186	    group.spawn_bg(no_wait=true, async fn() { errors.read(err) })
1187	    let status = child.wait()
1188	    while !output.finished {
1189	      @async.sleep(5)
1190	    }
1191	    wait_diagnostic_captures([errors])
1192	    (
1193	      status,
1194	      output.output.to_bytes(),
1195	      output.truncated,
1196	      errors.output.to_bytes(),
1197	      errors.truncated || !errors.finished,
1198	    )
1199	  })
1200	}
