1214	  let cancelled = @async.is_being_cancelled()
1215	  let timeout = error is @async.TimeoutError
1216	  save_diagnostic(
1217	    stage,
1218	    if cancelled {
1219	      "cancelled"
1220	    } else if timeout {
1221	      "timeout"
1222	    } else {
1223	      "failed"
1224	    },
1225	    error_type=if cancelled {
