1248	///|
1249	fn process_error_type(output : String) -> String {
1250	  let text = output.to_lower()
1251	  if text.contains("out of memory") || text.contains("cannot allocate memory") {
1252	    "memory_exhausted"
1253	  } else if text.contains("no space left on device") {
1254	    "disk_exhausted"
1255	  } else if text.contains("address already in use") ||
1256	    text.contains("addrinuse") {
1257	    "address_in_use"
1258	  } else if text.contains("permission denied (publickey") ||
1259	    text.contains("authentication failed") {
1260	    "authentication_failed"
1261	  } else if text.contains("host key verification failed") {
1262	    "host_key_failed"
1263	  } else if text.contains("connection refused") {
1264	    "connection_refused"
1265	  } else if text.contains("connection timed out") ||
1266	    text.contains("operation timed out") {
1267	    "connection_timeout"
1268	  } else if text.contains("could not resolve hostname") {
1269	    "name_resolution"
1270	  } else if text.contains("controlsocket") || text.contains("control socket") {
1271	    "control_socket"
1272	  } else if text.contains("build_vm:") {
1273	    "vm_boot"
1274	  } else if text.contains("create microsandbox vm") && text.contains("network:") {
1275	    "vm_network"
1276	  } else if text.contains("create microsandbox vm") && text.contains("mount:") {
1277	    "vm_mount"
1278	  } else if text.contains("ensure microsandbox final image") ||
1279	    text.contains("prepare microsandbox final image") {
1280	    "vm_image"
1281	  } else if text.contains("create microsandbox vm") {
1282	    "vm_create"
1283	  } else if text.contains("start microsandbox vm") {
1284	    "vm_start"
1285	  } else if text.contains("no such file or directory") ||
1286	    text.contains("not found") {
1287	    "missing_resource"
1288	  } else if text.contains("permission denied") {
1289	    "permission_denied"
1290	  } else if text.contains("database is locked") ||
1291	    text.contains("database locked") {
1292	    "database_locked"
1293	  } else if text.contains("too many open files") {
1294	    "file_limit"
1295	  } else {
1296	    "process_exit"
1297	  }
1298	}
