171	///|
172	fn diagnostic_json(
173	  value : Json,
174	  environment : Map[String, String],
175	  protected_secrets : Array[String],
176	  truncated : Ref[Bool],
177	  depth : Int32,
178	  stable_activity~ : Bool = false,
179	  secret_states~ : Bool = false,
180	) -> Json {
181	  if depth >= 64 {
182	    truncated.val = true
183	    return Json::string("[nested evidence omitted]")
184	  }
185	  match value {
186	    Json::Object(values) => {
187	      let result = Json::empty_object()
188	      for name, item in values {
189	        let key = name.to_lower().replace_all(old="_", new="")
190	        let safe_name = if stable_activity &&
191	          [
192	            "schemaVersion", "observedAt", "activity", "reason", "terminals", "chats",
193	            "errors", "worktreeId", "agent", "type", "state", "programState", "sessionId",
194	            "workspaceId", "source", "code", "id", "uid", "context", "provider",
195	            "identityVerified", "vmStatus", "outcome", "evidence", "evidenceTruncated",
196	            "workspaces", "discoveryErrors", "action", "failed", "detailsTruncated",
197	            "error", "autoStop",
198	          ].contains(name) {
199	          name
200	        } else {
201	          diagnostic_text(name, environment~, protected_secrets~)
202	        }
203	        if field(result, safe_name) is Some(_) {
204	          truncated.val = true
205	          continue
206	        }
207	        if safe_name.has_suffix("\n[error details incomplete or truncated]") {
208	          truncated.val = true
209	        }
210	        set_field(
211	          result,
212	          safe_name,
213	          if credential_field(name) || key == "pairingcode" {
214	            if secret_states &&
215	              field(item, "state") is Some(Json::String(state)) &&
216	              ["unset", "empty", "set"].contains(state) {
217	              let masked : Json = { "state": state }
218	              if field(item, "value") is Some(_) {
219	                set_field(masked, "value", Json::string("[redacted]"))
220	              }
221	              if field(item, "truncated") == Some(Json::boolean(true)) {
222	                set_field(masked, "truncated", Json::boolean(true))
223	                truncated.val = true
224	              }
225	              masked
226	            } else {
227	              Json::string("[redacted]")
228	            }
229	          } else if stable_activity &&
230	            name == "activity" &&
231	            (
232	              item == Json::string("idle") ||
233	              item == Json::string("active") ||
234	              item == Json::string("unknown")
235	            ) {
236	            item
237	          } else {
238	            diagnostic_json(
239	              item,
240	              environment,
241	              protected_secrets,
242	              truncated,
243	              depth + 1,
244	              stable_activity~,
245	              secret_states~,
246	            )
247	          },
248	        )
249	      }
250	      result
251	    }
252	    Json::Array(values) =>
253	      Json::array(
254	        values.map(item => {
255	          diagnostic_json(
256	            item,
257	            environment,
258	            protected_secrets,
259	            truncated,
260	            depth + 1,
261	            stable_activity~,
262	            secret_states~,
