364	async fn save_diagnostic(
365	  stage : String,
366	  status : String,
367	  exit_code? : Int32,
368	  error_type? : String,
369	  phase? : String,
370	  duration_ms? : Double,
371	  attempt? : Int32,
372	  retry_delay_ms? : Int32,
373	  timeout_ms? : Int32,
374	  os_errno? : Int32,
375	  source? : CreateEvidence,
376	  error_message? : String,
377	  details_truncated~ : Bool = false,
378	  tunnel_directory? : String,
379	  expected_workspace_uid? : String,
380	  observed_workspace_uid? : String,
381	  evidence? : Json,
382	  evidence_incomplete~ : Bool = false,
383	  evidence_stable_activity~ : Bool = false,
384	  recording? : Bool,
385	  environment? : Map[String, String],
386	  protected_secrets? : Array[String],
387	) -> Unit {
388	  if !recording.unwrap_or(
389	      @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") != Some("0"),
390	    ) {
391	    return
392	  }
393	  let event_time = @env.now()
394	  let event : Json = {
395	    "stage": stage,
396	    "status": status,
397	    "time": event_time.to_string(),
398	    "runId": recording_run_id,
399	    "adapterVersion": version,
400	  }
401	  if create_recording.attempt > 0 {
402	    set_field(
403	      event,
404	      "createAttempt",
405	      Json::number(create_recording.attempt.to_double()),
406	    )
407	    set_field(event, "createPhase", Json::string(create_recording.phase))
408	  }
409	  let process_environment = @env.get_env_vars()
410	  let secrets = [] + protected_secrets.unwrap_or([])

411	  if environment is Some(environment) {
412	    for secret in Progress::new("diagnostic-evidence", environment~).secrets {
413	      secrets.push(secret)
414	    }
415	  }
416	  if tunnel_directory is Some(directory) &&
417	    diagnostic_workspace_environments.get(directory) is Some(environment) {
418	    for secret in Progress::new("diagnostic-evidence", environment~).secrets {
419	      secrets.push(secret)
420	    }
421	  }
422	  if error_message is Some(message) {
423	    let message = diagnostic_text(
424	      message,
425	      environment=process_environment,
426	      protected_secrets=secrets,
427	    )
428	    set_field(event, "errorMessage", Json::string(message))
429	    set_field(
430	      event,
431	      "detailsTruncated",
432	      Json::boolean(
433	        details_truncated ||
434	        message == "[error details incomplete or truncated]" ||
435	        message.has_suffix("\n[error details incomplete or truncated]"),
436	      ),
437	    )
438	  }
439	  if tunnel_directory is Some(directory) {
440	    set_field(
441	      event,
442	      "tunnelDirectory",
443	      Json::string(
444	        diagnostic_text(
445	          directory,
446	          environment=process_environment,
447	          protected_secrets=secrets,
448	        ),
449	      ),
450	    )
451	  }
452	  for
453	    pair in [
454	      ("expectedWorkspaceUid", expected_workspace_uid),
455	      ("observedWorkspaceUid", observed_workspace_uid),
456	    ] {
457	    if pair.1 is Some(value) {
458	      set_field(
459	        event,
460	        pair.0,
461	        Json::string(
462	          diagnostic_text(
463	            value,
464	            environment=process_environment,
465	            protected_secrets=secrets,
466	          ),
467	        ),
468	      )
469	    }
470	  }
471	  let evidence_truncated : Ref[Bool] = { val: evidence_incomplete, }
472	  if source is Some(evidence) {
473	    let value = evidence.to_json()
474	    if value.stringify().length() <= 65536 {
475	      set_field(
476	        event,
477	        "source",
478	        diagnostic_json(
479	          value,
480	          process_environment,
481	          secrets,
482	          evidence_truncated,
483	          0,
484	          stable_activity=evidence_stable_activity,
485	        ),
486	      )
487	    } else {
488	      evidence_truncated.val = true
489	    }
490	  }
491	  if evidence is Some(value) {
492	    if value.stringify().length() <= 65536 {
493	      set_field(
494	        event,
495	        "evidence",
496	        diagnostic_json(
497	          value,
498	          process_environment,
499	          secrets,
500	          evidence_truncated,
501	          0,
502	          stable_activity=evidence_stable_activity,
503	          secret_states=stage == "server-environment",
504	        ),
505	      )
506	    } else {
507	      evidence_truncated.val = true
508	    }
509	  }
510	  if evidence_truncated.val {
511	    set_field(event, "evidenceTruncated", Json::boolean(true))
512	    set_field(event, "completeness", Json::string("partial"))
513	  }
514	  if os_errno is Some(code) && code > 0 && code < 4096 {
515	    set_field(event, "osErrno", Json::number(code.to_double()))
516	  }
517	  if exit_code is Some(code) {
518	    set_field(event, "exitCode", Json::number(code.to_double()))
519	  }
520	  for pair in [("errorType", error_type), ("phase", phase)] {
521	    if pair.1 is Some(text) {
522	      set_field(event, pair.0, Json::string(text))
523	    }
524	  }
525	  if duration_ms is Some(value) {
526	    set_field(event, "durationMs", Json::number(value))
527	  }
528	  if attempt is Some(value) {
529	    set_field(event, "attempt", Json::number(value.to_double()))
530	  }
531	  if timeout_ms is Some(value) {
532	    set_field(event, "timeoutMs", Json::number(value.to_double()))
533	  }
534	  if retry_delay_ms is Some(value) {
535	    set_field(event, "retryDelayMs", Json::number(value.to_double()))
536	  }
537	  let failed = error_type is Some(_) ||
538	    ["failed", "timeout", "cancelled", "warning", "process-error"].contains(
539	      status,
540	    )
541	  if diagnostic_pending.length() >= 64 {
542	    let mut evict = -1
543	    if failed {
544	      for index in diagnostic_pending_inflight.val..<diagnostic_pending.length() {
545	        if !diagnostic_pending[index].failed {
546	          evict = index
547	          break
548	        }
549	      }
550	      if evict < 0 &&
551	        diagnostic_pending_inflight.val < diagnostic_pending.length() {
552	        evict = diagnostic_pending_inflight.val
553	      }
554	    }
555	    if evict < 0 {
556	      diagnostic_recording_failed("buffer_full", phase="buffer", event_time~)
557	      return
558	    }
559	    let removed = diagnostic_pending.remove(evict)
560	    diagnostic_pending.push({ event, failed, time: event_time, })
561	    diagnostic_recording_failed(
562	      "buffer_full",
563	      phase="buffer",
564	      event_time=removed.time,
565	    )
566	    try_flush_diagnostic_recording()
567	    return
568	  }
569	  diagnostic_pending.push({ event, failed, time: event_time, })
570	  try_flush_diagnostic_recording()
571	}
