573	///|
574	async fn try_flush_diagnostic_recording() -> Unit {
575	  if diagnostic_write_active.val ||
576	    (diagnostic_pending.is_empty() && diagnostic_recording_health.dropped == 0) {
577	    return
578	  }
579	  diagnostic_write_active.val = true
580	  defer {
581	    diagnostic_write_active.val = false
582	  }
583	  let mut failure_phase = "directory"
584	  let mut health_changed = false
585	  @async.with_timeout(50, async fn() {
586	    let dir = adapter_state_home()
587	    @fs.mkdir(dir, permission=0o700, recursive=true, allow_exist=true)
588	    @fs.chmod(dir, 0o700)
589	    let path = dir + "/events.jsonl"
590	    let lock_path = dir + "/events.lock"
591	    failure_phase = "lock"
592	    if @fs.exists(lock_path) &&
593	      @fs.kind(lock_path, follow_symlink=false) != @fs.FileKind::Regular {
594	      diagnostic_recording_warning("invalid_lock", phase=failure_phase)
595	      return
596	    }
597	    let lock = @fs.open(
598	      lock_path,
599	      mode=ReadWrite,
600	      create_mode=OpenOrCreate,
601	      permission=0o600,
602	    )
603	    defer lock.close()
604	    if !lock.try_lock(Exclusive) {
605	      diagnostic_recording_warning("lock_busy", phase=failure_phase)
606	      return
607	    }
608	    failure_phase = "inspect"
609	    if @fs.exists(path) &&
610	      @fs.kind(path, follow_symlink=false) != @fs.FileKind::Regular {
611	      diagnostic_recording_warning("invalid_store", phase=failure_phase)
612	      return
613	    }
614	    let mut prefix = ""
615	    let mut replace = false
616	    if @fs.exists(path) {
617	      let file = @fs.open(path, mode=ReadOnly)
618	      defer file.close()
619	      let size = file.size()
620	      if size > 262144L {
621	        let marker = diagnostic_recording_event("rotated", "retention_limit")
622	        set_field(
623	          marker,
624	          "missingThroughTime",
625	          Json::string(@env.now().to_string()),
626	        )
627	        set_field(marker, "missingRange", Json::string("unknown"))
628	        prefix = marker.stringify() +
629	          "\n" +
630	          diagnostic_retained_records(file, size)
631	        replace = true
632	      } else if size > 0L {
633	        let tail = FixedArray::make(1, b'\x00')
634	        guard file.read_at(tail, position=size - 1L) == 1 else {
635	          raise AdapterError("Unable to inspect diagnostic record boundary")
636	        }
637	        if tail[0] != b'\n' {
638	          let bytes = FixedArray::make(size.to_int(), b'\x00')
639	          let read = file.read_at(bytes, position=0L)
640	          let mut complete = read
641	          while complete > 0 && bytes[complete - 1] != b'\n' {
642	            complete -= 1
643	          }
644	          prefix = @utf8.decode_lossy(
645	            bytes.unsafe_reinterpret_as_bytes()[:complete],
646	          )
647	          let marker = diagnostic_recording_event(
648	            "degraded",
649	            if read != size.to_int() {
650	              "short_read"
651	            } else {
652	              "incomplete_record"
653	            },
654	          )
655	          set_field(marker, "missingRange", Json::string("unknown"))
656	          prefix += marker.stringify() + "\n"
657	          replace = true
658	        }
659	      }
660	    }
661	    let recorded_drops = diagnostic_recording_health.dropped
662	    let incident_serial = diagnostic_recording_health.incident_serial
663	    if recorded_drops > 0 || diagnostic_recording_health.incident {
664	      let marker = diagnostic_recording_event(
665	        if recorded_drops > 0 {
666	          "degraded"
667	        } else {
668	          "recovered"
669	        },
670	        diagnostic_recording_health.reason,
671	      )
672	      if recorded_drops > 0 {
673	        set_field(
674	          marker,
675	          "droppedEvents",
676	          Json::number(recorded_drops.to_double()),
677	        )
678	        set_field(
679	          marker,
680	          "missingFromTime",
681	          Json::string(diagnostic_recording_health.first_dropped.to_string()),
682	        )
683	        set_field(
684	          marker,
685	          "missingThroughTime",
686	          Json::string(diagnostic_recording_health.last_dropped.to_string()),
687	        )
688	      } else {
689	        set_field(marker, "completeness", Json::string("complete"))
690	      }
691	      if diagnostic_recording_health.phase != "" {
692	        set_field(
693	          marker,
694	          "phase",
695	          Json::string(diagnostic_recording_health.phase),
696	        )
697	      }
698	      if diagnostic_recording_health.os_errno is Some(code) {
699	        set_field(marker, "osErrno", Json::number(code.to_double()))
700	      }
701	      prefix += marker.stringify() + "\n"
702	    }
703	    let count = diagnostic_pending.length()
704	    diagnostic_pending_inflight.val = count
705	    defer {
706	      diagnostic_pending_inflight.val = 0
707	    }
708	    let records = @buffer.Buffer(size_hint=4096)
709	    for index in 0..<count {
710	      records.write_string_utf8(
711	        diagnostic_pending[index].event.stringify() + "\n",
712	      )
713	    }
714	    let content = prefix + @utf8.decode_lossy(records.to_bytes())
715	    failure_phase = if replace { "replace" } else { "append" }
716	    if replace {
717	      let temporary = path + ".rotate." + proxy_pid().to_string()
718	      defer (@fs.remove(temporary) catch { _ => () })
719	      @fs.write_file(temporary, content, permission=0o600)
720	      @fs.rename(temporary, path, replace=true)
721	    } else {
722	      @fs.write_file(
723	        path,
724	        content,
725	        permission=0o600,
726	        append=true,
727	        create_mode=OpenOrCreate,
728	      )
729	    }
730	    for _ in 0..<count {
731	      ignore(diagnostic_pending.remove(0))
732	    }
733	    diagnostic_recording_health.dropped -= recorded_drops
734	    if diagnostic_recording_health.incident_serial == incident_serial {
735	      diagnostic_recording_health.incident = false
736	      health_changed = true
737	    }
738	  }) catch {
739	    error =>
740	      if !@async.is_being_cancelled() {
741	        diagnostic_recording_warning(
742	          if error is @async.TimeoutError {
743	            "store_timeout"
744	          } else {
745	            "store_unavailable"
746	          },
747	          phase=failure_phase,
748	          os_errno?=match error {
749	            @os_error.OSError(code, ..) => Some(code)
750	            _ => None
751	          },
752	        )
753	      }
754	  }
755	  if health_changed {
756	    publish_diagnostic_health()
757	    if diagnostic_recording_health.incident {
758	      publish_diagnostic_health()
759	    }
760	  }
761	}
