763	///|
764	async fn flush_diagnostic_recording() -> Unit {
765	  if diagnostic_pending.is_empty() && diagnostic_recording_health.dropped == 0 {
766	    return
767	  }
768	  @async.with_timeout(1000, async fn() {
769	    while !diagnostic_pending.is_empty() ||
770	          diagnostic_recording_health.dropped > 0 {
771	      try_flush_diagnostic_recording()
772	      if !diagnostic_pending.is_empty() ||
773	        diagnostic_recording_health.dropped > 0 {
774	        @async.sleep(25)
775	      }
776	    }
777	  }) catch {
778	    error => if @async.is_being_cancelled() { raise error }
779	  }
780	}
