1351	///|
1352	fn diagnostic_value(value : String?, kind : DiagnosticValueKind) -> Json {
1353	  match value {
1354	    None => { "state": "unset" }
1355	    Some("") => { "state": "empty" }
1356	    Some(text) => {
1357	      let valid = match kind {
1358	        Commit => valid_commit(text)
1359	        Workspace => valid_workspace_id(text)
1360	        Identity => text.length() <= 128 && valid_context(text)
1361	        RefName => diagnostic_ref(text)
1362	      }
1363	      let credential_form = text
1364	        .split("/")
1365	        .iter()
1366	        .any(part => {
1367	          [
1368	            "ghp_", "gho_", "ghu_", "ghs_", "ghr_", "github_pat_", "glpat-", "sk-",
1369	            "eyJ",
1370	          ]
1371	          .iter()
1372	          .any(prefix => part.has_prefix(prefix))
1373	        })
1374	      if valid && !credential_form {
1375	        { "state": "valid", "value": text }
1376	      } else {
1377	        { "state": "invalid" }
1378	      }
1379	    }
1380	  }
1381	}
