1383	///|
1384	// A recording grammar, never a replacement for checkout validation. Excludes
1385	// URLs, credential forms, control characters and Git's invalid ref syntax.
1386	fn diagnostic_ref(text : String) -> Bool {
1387	  text.length() <= 1024 &&
1388	  !text.has_prefix("-") &&
1389	  !text.contains("..") &&
1390	  text
1391	  .split("/")
1392	  .iter()
1393	  .all(part => {
1394	    part != "" &&
1395	    !part.has_prefix(".") &&
1396	    !part.has_suffix(".") &&
1397	    !part.has_suffix(".lock")
1398	  }) &&
1399	  text
1400	  .iter()
1401	  .all(c => {
1402	    (c >= 'a' && c <= 'z') ||
1403	    (c >= 'A' && c <= 'Z') ||
1404	    (c >= '0' && c <= '9') ||
1405	    c == '/' ||
1406	    c == '-' ||
1407	    c == '_' ||
1408	    c == '.'
1409	  })
1410	}
