1413	fn CreateEvidence::to_json(self : CreateEvidence) -> Json {
1414	  match self {
1415	    VolumeCleanup(volume, plan) => { "volume": volume, "cleanup": plan }
1416	    IdentitySelection(slug, id) =>
1417	      { "repositorySlug": redact_credentials(slug), "workspaceId": id }
1418	    Storage(volume, root) =>
