 867	fn diagnostic_partial_secret(text : String, secrets : Array[String]) -> String {
 868	  let chars = text.iter().to_array()
 869	  let mut boundary = chars.length()
 870	  for secret in secrets {
 871	    let value = secret.iter().to_array()
 872	    if value.length() == 0 || text.has_suffix(secret) {
 873	      continue
 874	    }
 875	    let limit = if value.length() - 1 < boundary {
 876	      value.length() - 1
 877	    } else {
 878	      boundary
 879	    }
 880	    if limit == 0 {
 881	      continue
 882	    }
 883	    let prefixes = FixedArray::make(limit, 0)
 884	    let mut matched = 0
 885	    for index in 1..<limit {
 886	      while matched > 0 && value[matched] != value[index] {
 887	        matched = prefixes[matched - 1]
 888	      }
 889	      if value[matched] == value[index] {
 890	        matched += 1
 891	      }
 892	      prefixes[index] = matched
 893	    }
 894	    matched = 0
 895	    for index in 0..<boundary {
 896	      while matched > 0 && (matched == limit || value[matched] != chars[index]) {
 897	        matched = prefixes[matched - 1]
 898	      }
 899	      if matched < limit && value[matched] == chars[index] {
 900	        matched += 1
 901	      }
 902	    }
 903	    boundary -= matched
 904	  }
 905	  if boundary == chars.length() {
 906	    text
 907	  } else {
 908	    character_text(chars, 0, boundary) + "[redacted]"
 909	  }
