314	///|
315	async fn Progress::message(
316	  self : Progress,
317	  text : String,
318	  debug~ : Bool,
319	  warning~ : Bool,
320	  emit~ : Bool = true,
321	) -> Unit {
322	  for line in text.split("\n") {
323	    let text = line.trim().to_owned()
324	    if text == "" {
325	      continue
326	    }
327	    guard self.safe_message(text) is Some(safe) else {
328	      self.details_truncated = true
329	      continue
330	    }
331	    if !debug || warning {
332	      self.remember(safe, warning~)
333	    }
334	    if !emit {
335	      continue
336	    }
337	    if safe.has_prefix("#") {
338	      guard safe.split_once(" ") is Some((id, rest)) &&
339	        id.length() > 1 &&
340	        id[1:].iter().all(c => c >= '0' && c <= '9') else {
341	        continue
342	      }
343	      let detail = rest.trim().to_owned()
344	      guard detail.has_prefix("[") ||
345	        detail.has_prefix("DONE") ||
346	        detail.has_prefix("ERROR") ||
347	        detail.has_prefix("CACHED") else {
348	        continue
349	      }
350	      if detail.has_prefix("ERROR") && debug && !warning {
351	        self.remember(safe, warning=true)
352	      }
353	      if self.builds.get(id.to_owned()) == Some(detail) {
354	        continue
355	      }
356	      if self.builds.length() < 2048 || self.builds.contains(id.to_owned()) {
357	        self.builds.set(id.to_owned(), detail)
358	      }
359	      progress_message("Build " + id.to_owned() + ": " + detail)
360	    } else if classic_build_step(safe) {
361	      // Classic RUN output has no prefix. Only its own completion marker
362	      // ends this mode; phase events on another pipe can arrive ahead of it.
363	      self.classic_build = true
364	      progress_message("Build " + safe)
365	    } else if safe.has_prefix("Successfully built ") ||
366	      safe.has_prefix("Successfully tagged ") {
367	      self.classic_build = false
368	      progress_message("Build: " + safe)
369	    } else if self.classic_build && !warning {
370	      continue
371	    } else if !debug && !safe.has_prefix("{") && !safe.has_prefix("[") {
372	      progress_message(self.stage + ": " + safe)
373	    } else if !debug && safe.has_prefix("[credential") {
374	      progress_message(self.stage + ": " + safe)
