379	///|
380	async fn Progress::line(
381	  self : Progress,
382	  line : String,
383	  statuses~ : Bool,
384	  messages~ : Bool,
385	) -> Unit {
386	  if line.trim() == "" {
387	    return
388	  }
389	  let event = @json.parse(line) catch { _ => Json::null() }
390	  if field(event, "kind") == Some(Json::string("status")) {
391	    if field(event, "state") == Some(Json::string("failed")) &&
392	      field(event, "error") is Some(error) {
393	      for name in ["message", "hint"] {
394	        if field(error, name) is Some(Json::String(text)) {
395	          self.message(
396	            text,
397	            debug=false,
398	            warning=true,
399	            emit=messages || statuses,
400	          )
401	        }
402	      }
403	    }
404	    if statuses || messages {
405	      self.status(event)
406	    }
407	    return
408	  }
409	  // Result envelopes and arbitrary structured responses are never log text.
410	  if field(event, "kind") == Some(Json::string("result")) {
411	    return
412	  }
413	  if event is Json::Object(_) {
414	    let kind = field(event, "kind")
415	    guard kind == None ||
416	      kind == Some(Json::string("log")) ||
417	      kind == Some(Json::string("error")) else {
418	      return
419	    }
420	    let message = match field(event, "msg") {
421	      Some(value) => Some(value)
422	      None =>
423	        match field(event, "message") {
424	          Some(value) => Some(value)
425	          None =>
426	            match field(event, "error") {
427	              Some(Json::Object(_) as value) => field(value, "message")
428	              value => value
429	            }
430	        }
431	    }
432	    guard message is Some(Json::String(text)) else { return }
433	    let level = field(event, "level")
434	    self.message(
435	      text,
436	      debug=level == Some(Json::string("debug")) ||
437	        level == Some(Json::string("trace")),
438	      warning=kind == Some(Json::string("error")) ||
439	        level == Some(Json::string("warn")) ||
440	        level == Some(Json::string("error")),
441	      emit=messages || (statuses && kind != None),
442	    )
443	  } else {
444	    if event != Json::null() {
445	      return
446	    }
447	    // Malformed JSON and binary output are not a safe free-text fallback.
448	    let text = line.trim().to_owned()
449	    if text.has_prefix("[ERROR]") || text.has_prefix("[WARN]") {
450	      self.message(text, debug=false, warning=true, emit=messages)
451	      return
452	    }
453	    if text.has_prefix("{") || text.has_prefix("[") {
454	      self.details_truncated = true
455	      return
456	    }
457	    self.message(
458	      text,
459	      debug=text.contains(" DEBUG ") ||
460	        text.contains(" TRACE ") ||
461	        text.has_prefix("DEBUG ") ||
462	        text.has_prefix("TRACE "),
463	      warning=text.contains(" WARN ") ||
464	        text.contains(" ERROR ") ||
465	        text.has_prefix("WARN ") ||
466	        text.has_prefix("ERROR "),
467	      emit=messages,
468	    )
469	  }
470	}
