109	///|
110	fn redact_credentials(text : String) -> String {
111	  let chars = text.iter().to_array()
112	  let buffer = @buffer.Buffer(size_hint=text.length())
113	  let mut i = 0
114	  let mut url = false
115	  while i < chars.length() {
116	    if credential_space(chars[i]) || ['"', '\''].contains(chars[i]) {
117	      url = false
118	    }
119	    if chars[i] == ':' &&
120	      i + 2 < chars.length() &&
121	      chars[i + 1] == '/' &&
122	      chars[i + 2] == '/' {
123	      url = true
124	      buffer.write_string_utf8("://")
125	      i += 3
126	      let mut end = i
127	      let mut user_end = None
128	      while end < chars.length() &&
129	            !credential_end(chars[end]) &&
130	            !['/', '?'].contains(chars[end]) {
131	        if chars[end] == '@' {
132	          user_end = Some(end)
133	        }
134	        end += 1
135	      }
136	      if user_end is Some(end) {
137	        buffer.write_string_utf8("[redacted]@")
138	        i = end + 1
139	      }
140	      continue
141	    }
142	    if url && ['?', '&'].contains(chars[i]) {
143	      let start = i
144	      i += 1
145	      while i < chars.length() && !credential_end(chars[i]) && chars[i] != '=' {
146	        i += 1
147	      }
148	      let name = credential_parameter(character_text(chars, start + 1, i))
149	      if i < chars.length() && chars[i] == '=' {
150	        i += 1
151	        buffer.write_string_utf8(character_text(chars, start, i))
152	        if credential_field(name) || name.to_lower() == "key" {
153	          if i + 10 <= chars.length() &&
154	            character_text(chars, i, i + 10) == "[redacted]" {
155	            i += 10
156	          }
157	          while i < chars.length() && !credential_end(chars[i]) {
158	            i += 1
159	          }
160	          buffer.write_string_utf8("[redacted]")
161	        }
162	      } else {
163	        buffer.write_string_utf8(character_text(chars, start, i))
164	      }
165	      continue
166	    }
167	    if credential_word(chars[i]) && (i == 0 || !credential_word(chars[i - 1])) {
168	      let start = i
169	      let mut end = i
170	      while end < chars.length() && credential_word(chars[end]) {
171	        end += 1
172	      }
173	      let word = character_text(chars, start, end)
174	      let lower = word.to_lower()
175	      if [
176	          "ghp_", "gho_", "ghu_", "ghs_", "ghr_", "github_pat_", "sk-", "age-secret-key-",
177	        ]
178	        .iter()
179	        .any(prefix => lower.has_prefix(prefix)) ||
180	        (word.has_prefix("eyJ") && end < chars.length() && chars[end] == '.') {
181	        while end < chars.length() && !credential_end(chars[end]) {
182	          end += 1
183	        }
184	        buffer.write_string_utf8("[redacted]")
185	        i = end
186	        continue
187	      }
188	      let mut separator = end
189	      if separator < chars.length() && ['"', '\''].contains(chars[separator]) {
190	        separator += 1
191	      }
192	      while separator < chars.length() && credential_space(chars[separator]) {
193	        separator += 1
194	      }
195	      let mut previous = start
196	      while previous > 0 && credential_space(chars[previous - 1]) {
197	        previous -= 1
198	      }
199	      let field_start = previous == 0 ||
200	        [';', ',', '{', '"', '\'', '?', '&'].contains(chars[previous - 1])
201	      let option = word.has_prefix("--")
202	      let prose_credential = (
203	          ["credential", "credentials"].contains(lower) && !field_start
204	        ) ||
205	        lower == "ssh_inject_git_credentials"
206	      let assignment = separator < chars.length() &&
207	        (
208	          chars[separator] == '=' ||
209	          (chars[separator] == ':' && !prose_credential)
210	        )
211	      if credential_field(word) && (assignment || (option && separator > end)) {
212	        let mut value = if assignment { separator + 1 } else { separator }
213	        while value < chars.length() && credential_space(chars[value]) {
214	          value += 1
215	        }
216	        buffer.write_string_utf8(character_text(chars, start, value))
217	        let quoted_key = start > 0 &&
218	          end < chars.length() &&
219	          ['"', '\''].contains(chars[start - 1]) &&
220	          chars[start - 1] == chars[end]
221	        if ["cookie", "set-cookie", "--cookie"].contains(lower) && !quoted_key {
222	          buffer.write_string_utf8("[redacted]")
223	          i = chars.length()
224	        } else if value + 10 <= chars.length() &&
225	          character_text(chars, value, value + 10) == "[redacted]" {
226	          buffer.write_string_utf8("[redacted]")
227	          i = value + 10
228	          while i < chars.length() && !credential_end(chars[i]) {
229	            i += 1
230	          }
231	        } else if value < chars.length() && ['"', '\''].contains(chars[value]) {
232	          let quote = chars[value]
233	          buffer.write_char_utf8(quote)
234	          value += 1
235	          while value < chars.length() && chars[value] != quote {
236	            if chars[value] == '\\' && value + 1 < chars.length() {
237	              value += 1
238	            }
239	            value += 1
240	          }
241	          buffer.write_string_utf8("[redacted]")
242	          i = value
243	        } else {
244	          let mut value_end = value
245	          while value_end < chars.length() && !credential_end(chars[value_end]) {
246	            value_end += 1
247	          }
248	          let scheme = character_text(chars, value, value_end).to_lower()
249	          if scheme == "bearer" || scheme == "basic" {
250	            while value_end < chars.length() &&
251	                  credential_space(chars[value_end]) {
252	              value_end += 1
253	            }
254	            buffer.write_string_utf8(character_text(chars, value, value_end))
255	            value = value_end
256	            while value_end < chars.length() &&
257	                  !credential_end(chars[value_end]) {
258	              value_end += 1
259	            }
260	          }
261	          if value + 10 <= chars.length() &&
262	            character_text(chars, value, value + 10) == "[redacted]" {
263	            value_end = value + 10
264	          }
265	          if value_end > value {
266	            buffer.write_string_utf8("[redacted]")
267	          }
268	          i = value_end
269	        }
270	        continue
271	      }
272	      buffer.write_string_utf8(word)
273	      i = end
274	      continue
275	    }
276	    buffer.write_char_utf8(chars[i])
277	    i += 1
278	  }
279	  @utf8.decode_lossy(buffer.to_bytes())
280	}
