308	  let values : Array[Array[Char]] = []
309	  for secret in secrets {
310	    if secret.length() <= text.length() {
311	      values.push(secret.iter().to_array())
312	    }
313	  }
314	  let result = @buffer.Buffer(size_hint=text.length())
315	  let mut i = 0
316	  while i < chars.length() {
317	    let mut matched = 0
318	    for index in 0..<values.length() {
319	      let value = values[index]
320	      let mut matches = value.length() > 0 &&
321	        i + value.length() <= chars.length()
322	      if matches {
323	        for j in 0..<value.length() {
324	          if chars[i + j] != value[j] {
325	            matches = false
326	            break
327	          }
328	        }
329	      }
330	      if matches &&
331	        (
332	          value.length() > 10 ||
333	          i + 10 > chars.length() ||
334	          character_text(chars, i, i + 10) != "[redacted]"
335	        ) {
336	        matched = value.length()
337	        break
338	      }
339	    }
340	    if matched > 0 {
341	      result.write_string_utf8("[redacted]")
342	      i += matched
343	    } else if i + 10 <= chars.length() &&
344	      character_text(chars, i, i + 10) == "[redacted]" {
345	      result.write_string_utf8("[redacted]")
346	      i += 10
347	    } else {
348	      result.write_char_utf8(chars[i])
