 69	  }
 70	  let socket = @socket.Tcp::connect(
 71	    @socket.Addr::parse("127.0.0.1:" + port.to_string()),
 72	  )
 73	  defer socket.close()
 74	  let peer = read_registration(socket, 4096)
 75	  guard field(peer, "protocol") == Some(Json::number(1)) &&
 76	    field(peer, "pid") == field(descriptor, "pid") &&
 77	    field(peer, "start") == field(descriptor, "start") else {
 78	    raise AdapterError("Supervisor registration endpoint changed")
 79	  }
 80	  let environment = environment.unwrap_or_else(() => {
 81	    let values = Json::empty_object()
 82	    for (name, value) in @env.get_env_vars() {
 83	      set_field(values, name, Json::string(value))
 84	    }
 85	    values
 86	  })
 87	  write_registration(socket, {
 88	    "directory": directory,
 89	    "environment": environment,
 90	  })
 91	  let reply = read_registration(socket, 4096)
 92	  guard field(reply, "accepted") == Some(Json::boolean(true)) else {
 93	    raise AdapterError("Supervisor rejected workspace registration")
 94	  }
 95	  if field(field(reply, "diagnosticHealth").unwrap_or(Json::null()), "status") ==
 96	    Some(Json::string("degraded")) {
 97	    progress_write(
 98	      "orca-env-devsy: warning: supervisor diagnostic recording is unavailable\n",
 99	    )
100	  }
101	}
