156	        "supervisor-registration",
157	        "success",
158	        tunnel_directory=directory,
159	        recording=true,
160	      )
161	    }
162	    write_registration(socket, {
163	      "accepted": true,
164	      "diagnosticHealth": diagnostic_health_snapshot(),
165	    })
